-- PRIVATE / DEFAULT OFF. Normal-session transport, redacted participant and
-- blind official context. No new grants, provider activation or photo service.
begin;
create function app.modern_manual_playoff_transport_enabled_v1()returns boolean language sql stable set search_path=''as $$select false$$;
create function public.get_modern_manual_playoff_context_v1(tid uuid,eid uuid,gid uuid,number integer,purpose text)returns jsonb language plpgsql security definer set search_path=''set timezone='UTC'as $$
declare actor uuid;g app.modern_manual_playoff_generations_v1%rowtype;gg app.modern_manual_playoff_games_v1%rowtype;own app.modern_manual_playoff_evidence_v1%rowtype;handoff app.modern_manual_playoff_evidence_v1%rowtype;capture app.modern_manual_playoff_evidence_v1%rowtype;review app.modern_manual_playoff_evidence_v1%rowtype;adjudication app.modern_manual_playoff_evidence_v1%rowtype;
 participant uuid;identity uuid;source jsonb;state jsonb;players jsonb;papers integer;revision integer;own_confirmed boolean;can_amend boolean;can_capture boolean;can_review boolean;can_adjudicate boolean;originals jsonb;begin
 if app.modern_manual_playoff_transport_enabled_v1()is distinct from true or app.modern_manual_playoff_enabled_v1()is distinct from true then return null;end if;actor:=app.manual_mixed_handoff_actor_v1();if actor is null or purpose is null or purpose not in('player','paper','adjudication')then return null;end if;
 select*into g from app.modern_manual_playoff_generations_v1 where id=gid and tournament_id=tid and event_id=eid;if g.id is null or number is null or number<1 or number>g.maximum_games then return null;end if;
 if actor=(g.source_capture->'profiles'->>0)::uuid and g.source_capture->'modes'->>0='digital'then participant:=g.side_a_participant_id;elsif actor=(g.source_capture->'profiles'->>1)::uuid and g.source_capture->'modes'->>1='digital'then participant:=g.side_b_participant_id;end if;
 identity:=app.modern_manual_playoff_independent_v1(actor,gid);if purpose='player'and participant is null or purpose<>'player'and identity is null then return null;end if;
 source:=app.modern_manual_playoff_source_v1(g.actor_id,tid,eid,g.qualification_id,g.slot);
 if source->>'status'is distinct from'source_available'or source->>'currentGenerationId'is distinct from gid::text or source->>'sourceDigest'is distinct from g.source_digest or source->'source'is distinct from g.source_capture then return null;end if;
 select*into gg from app.modern_manual_playoff_games_v1 where generation_id=gid and game_number=number;state:=coalesce(app.modern_manual_playoff_game_state_v1(gg.id),jsonb_build_object('verified',false,'disputed',false,'provisionalWinnerId',null));
 select count(*)into papers from jsonb_array_elements(g.source_capture->'modes')x where x='"paper"'::jsonb;
 select coalesce(max(e.revision),0)into revision from app.modern_manual_playoff_evidence_v1 e where e.game_id=gg.id;
 select*into own from app.modern_manual_playoff_evidence_v1 e where e.game_id=gg.id and e.actor_id=actor and e.action in('digital-submit','digital-amend')order by e.revision desc limit 1;
 select exists(select 1 from app.modern_manual_playoff_evidence_v1 e where e.game_id=gg.id and e.actor_id=actor and e.action='digital-confirm'and e.target_id=own.id)into own_confirmed;
 select*into handoff from app.modern_manual_playoff_evidence_v1 e where e.game_id=gg.id and e.actor_id=actor and e.action in('handoff-yes','handoff-no')order by e.revision desc limit 1;
 select*into capture from app.modern_manual_playoff_evidence_v1 where id=(state->>'captureId')::uuid;select*into review from app.modern_manual_playoff_evidence_v1 where id=(state->>'reviewId')::uuid;select*into adjudication from app.modern_manual_playoff_evidence_v1 where id=(state->>'adjudicationId')::uuid;
 can_amend:=purpose='player'and own.id is not null and not own_confirmed and not exists(select 1 from app.modern_manual_playoff_evidence_v1 e where e.game_id=gg.id and e.action in('handoff-yes','handoff-no','paper-capture','paper-review','adjudicate'))and not exists(select 1 from app.modern_manual_playoff_games_v1 x join app.modern_manual_playoff_evidence_v1 e on e.game_id=x.id where x.generation_id=gid and x.game_number>number);
 can_capture:=purpose='paper'and papers>0 and capture.id is null and state->'disputed'='false'::jsonb and actor is distinct from adjudication.actor_id and exists(select 1 from app.tournament_roles where tournament_id=tid and profile_id=actor and role='cross_checker')and(papers=2 or state->>'handoffId'is not null);
 can_review:=purpose='paper'and capture.id is not null and review.id is null and capture.actor_id<>actor and actor is distinct from adjudication.actor_id and state->'disputed'='false'::jsonb;
 can_adjudicate:=purpose='adjudication'and state->'disputed'='true'::jsonb and actor is distinct from capture.actor_id and actor is distinct from review.actor_id and not exists(select 1 from app.modern_manual_playoff_games_v1 x join app.modern_manual_playoff_evidence_v1 e on e.game_id=x.id where x.generation_id=gid and x.game_number>number);
 if purpose='adjudication'and not coalesce(can_adjudicate,false)then return null;end if;
 select jsonb_agg(jsonb_build_object('participantId',p.id,'name',q.display_name_snapshot,'tournamentPlayerId',a.verification_id,'mode',g.source_capture->'modes'->(i::integer-1))order by i)into players
 from jsonb_array_elements_text(g.source_capture->'participants')with ordinality x(id,i)join app.event_participants p on p.id=x.id::uuid and p.tournament_id=tid and p.event_id=eid join app.qualification_result_rows q on q.result_version_id=g.qualification_id and q.participant_id=p.id join app.initial_seating_assignments a on a.tournament_id=tid and a.roster_entry_id=p.roster_entry_id;
 if jsonb_array_length(players)<>2 then return null;end if;
 -- Only the adjudication workflow gets conflicting originals, AFTER dispute
 -- and independent admission. Ordinary blind re-entry never receives them.
 if purpose='adjudication'then select jsonb_agg(jsonb_build_object('evidenceId',e.id,'action',e.action,'version',e.revision,'winnerId',e.winner_id,'paperClaims',e.paper_claims,'reason',e.reason)order by e.revision)into originals from app.modern_manual_playoff_evidence_v1 e where e.game_id=gg.id;end if;
 if app.manual_mixed_handoff_actor_v1()is distinct from actor or(purpose<>'player'and app.modern_manual_playoff_independent_v1(actor,gid)is distinct from identity)then return null;end if;
 return jsonb_build_object('kind','modern-manual-playoff-context-v1','actorId',actor,'tournamentId',tid,'eventId',eid,'generationId',gid,'qualificationId',g.qualification_id,'slot',g.slot,'round',g.round_name,'sourceDigest',g.source_digest,'gameNumber',number,'gameId',gg.id,'version',revision,'maximumGames',g.maximum_games,'winsRequired',g.wins_required,'purpose',purpose,'players',players,'actorParticipantId',participant,
 'ownSubmission',case when purpose='player'and own.id is not null then jsonb_build_object('id',own.id,'winnerId',own.winner_id)else null end,'ownConfirmed',purpose='player'and own_confirmed,'ownHandoff',case when purpose='player'and handoff.id is not null then handoff.action else null end,
 'captureTargetId',case when can_review then capture.id else null end,'adjudicationTargetId',case when can_adjudicate then coalesce(review.id,capture.id,(state->>'handoffId')::uuid)else null end,'captureResolutionId',case when can_capture then adjudication.id else null end,
 'canAmend',coalesce(can_amend,false),'canCapture',coalesce(can_capture,false),'canReview',coalesce(can_review,false),'canAdjudicate',coalesce(can_adjudicate,false),'originals',originals,'disputed',state->'disputed','verified',state->'verified','awaitingPaperReview',papers>0 and state->'verified'='false'::jsonb and state->'disputed'='false'::jsonb,'canProceedTentatively',state->>'provisionalWinnerId'is not null and state->'disputed'='false'::jsonb,'seriesComplete',exists(select 1 from app.modern_manual_playoff_results_v1 where generation_id=gid),'financialHold',app.modern_manual_playoff_financial_hold_v1(tid,eid),'moneyMoved',false);
exception when lock_not_available then return null;end$$;
create function public.get_modern_manual_playoff_directory_v1(tid uuid)returns jsonb language plpgsql security definer set search_path=''as $$
declare actor uuid;g record;c jsonb;entries jsonb:='[]';begin
 if app.modern_manual_playoff_transport_enabled_v1()is distinct from true then return null;end if;actor:=app.manual_mixed_handoff_actor_v1();if actor is null then return null;end if;
 for g in select distinct on(event_id,qualification_id,slot)*from app.modern_manual_playoff_generations_v1 where tournament_id=tid order by event_id,qualification_id,slot,version desc limit 100 loop
  c:=public.get_modern_manual_playoff_context_v1(tid,g.event_id,g.id,1,'player');if c is not null then entries:=entries||jsonb_build_array(jsonb_build_object('eventId',g.event_id,'generationId',g.id,'slot',g.slot,'round',g.round_name,'purpose','player'));end if;
  c:=public.get_modern_manual_playoff_context_v1(tid,g.event_id,g.id,1,'paper');if c is not null then entries:=entries||jsonb_build_array(jsonb_build_object('eventId',g.event_id,'generationId',g.id,'slot',g.slot,'round',g.round_name,'purpose','paper'));end if;
 end loop;return jsonb_build_object('kind','modern-manual-playoff-directory-v1','actorId',actor,'tournamentId',tid,'entries',entries);
end$$;
create function public.record_modern_manual_playoff_provider_v1(tid uuid,eid uuid,request jsonb)returns jsonb language plpgsql security definer set search_path=''as $$begin
 if app.modern_manual_playoff_transport_enabled_v1()is distinct from true or not exists(select 1 from app.modern_manual_playoff_generations_v1 where id=(request->>'generationId')::uuid and tournament_id=tid and event_id=eid)then return null;end if;return app.record_modern_manual_playoff_evidence_v1(request);end$$;
create function public.get_modern_manual_playoff_operation_provider_v1(tid uuid,eid uuid,request jsonb)returns jsonb language plpgsql security definer set search_path=''as $$begin
 if app.modern_manual_playoff_transport_enabled_v1()is distinct from true or not exists(select 1 from app.modern_manual_playoff_generations_v1 where id=(request->>'generationId')::uuid and tournament_id=tid and event_id=eid)then return null;end if;return app.get_modern_manual_playoff_operation_v1((request->>'operationId')::uuid,request);end$$;
do $$declare s text;begin foreach s in array array['app.modern_manual_playoff_transport_enabled_v1()','public.get_modern_manual_playoff_context_v1(uuid,uuid,uuid,integer,text)','public.get_modern_manual_playoff_directory_v1(uuid)','public.record_modern_manual_playoff_provider_v1(uuid,uuid,jsonb)','public.get_modern_manual_playoff_operation_provider_v1(uuid,uuid,jsonb)']loop execute format('alter function %s owner to postgres',s);execute format('revoke all on function %s from public,anon,authenticated,service_role',s);end loop;end$$;
commit;
